nextflow_process {

    name "Test Process TRTOOLS_DUMPSTR"
    script "../main.nf"
    process "TRTOOLS_DUMPSTR"

    tag "modules"
    tag "modules_nfcore"
    tag "gangstr"
    tag "trtools"
    tag "trtools/dumpstr"

    setup {
        run("GANGSTR") {
            script "modules/nf-core/gangstr/main.nf"

            process {
                """
                bed = Channel.of(file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.bed', checkIfExists: true))
                    .map({ bed ->
                        def content = bed.text.replace('\\n', '').tokenize('\\t')
                        content.addAll(["5","CGCGC"])
                        [ content.join('\\t') ]
                    })
                    .collectFile( newLine: true ) { content ->
                        [ "genome.bed", content[0] ]
                    }

                input[0] = Channel.of([
                    [id:'test'],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/cram/test.paired_end.sorted.cram', checkIfExists:true),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/cram/test.paired_end.sorted.cram.crai', checkIfExists:true)
                ]).combine(bed)

                input[1] = file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.fasta', checkIfExists:true)
                input[2] = file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.fasta.fai', checkIfExists:true)
                """
            }
        }
    }

    test("homo_sapiens - gangstr vcf") {

        when {
            process {
                """
                input[0] = GANGSTR.out.vcf
                input[1] = Channel.of([[], []])
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(
                    path(process.out.vcf.get(0).get(1)).vcf.summary,
                    file(process.out.tbi[0][1]).name,
                    process.out.samplog,
                    process.out.loclog,
                    process.out.findAll { key, val -> key.startsWith('versions') }
                ).match() }
            )
        }
    }

    test("homo_sapiens - gangstr vcf -- stub") {

        options "-stub"

        when {
            process {
                """
                input[0] = GANGSTR.out.vcf
                input[1] = Channel.of([[], []])
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }
}

